/*!
 * @file      ols_coeffs.h
 * @brief     Rate-change filter and the overlap-save FIR filters for E04.
 *
 *            fs = 48000 Hz, low rate 16000 Hz (factor 3). Prototype: 90-tap
 *            Kaiser-windowed low-pass, pass band to 6000 Hz, 60 dB target from
 *            8000 Hz. FIR filters: Hamming-windowed low-passes of order 255 and 1023
 *            at the low rate, -6 dB at 2000 Hz. Overlap-save: 512-point FFT, hop 256.
 *
 *            Generated by `uv run coursework/E04-overlap-save/design.py`;
 *            edit the design there, not this file.
 */

#ifndef __OLS_COEFFS_H__
#define __OLS_COEFFS_H__

/*
 * Low-pass prototype h[0] .. h[N-1] at the codec rate, unity gain
 * at DC; the decimator applies it as is, the interpolator scaled
 * by OLS_FACTOR.
 */
#define OLS_SAMPLE_RATE (48000u)
#define OLS_FACTOR (3u)
#define OLS_RATE_TAPS (90u)
extern const float Rate16kTaps[OLS_RATE_TAPS];

/*
 * Order-255 low-pass at the low rate, h[0] .. h[255]: one
 * partition of OLS_HOP taps. Overlap-save frames are OLS_FFT_LEN
 * samples and hop by OLS_HOP.
 */
#define OLS_FFT_LEN (512u)
#define OLS_HOP (256u)
#define OLS_FIR255_TAPS (256u)
extern const float Fir255Taps[OLS_FIR255_TAPS];

/*
 * Order-1023 low-pass at the low rate, h[0] .. h[1023], for the
 * partitioned filter: OLS_FIR1023_PARTS partitions of OLS_HOP taps.
 */
#define OLS_FIR1023_TAPS (1024u)
#define OLS_FIR1023_PARTS (4u)
extern const float Fir1023Taps[OLS_FIR1023_TAPS];

#endif /* __OLS_COEFFS_H__ */
